const levelFor = (score: number) => score >= 90 ? "EE1" : score >= 75 ? "EE2" : score >= 58 ? "ME1" : score >= 41 ? "ME2" : score >= 31 ? "AE1" : score >= 21 ? "AE2" : score >= 11 ? "BE1" : "BE2";
